1	#!/usr/bin/env node
2	/* Differential harness: run a case list through both implementations. */
3	import { spawnSync } from 'node:child_process';
4	import { readFileSync } from 'node:fs';
5	
6	const REF = '/workspace/dataset/test10_executable';
7	const CASES = JSON.parse(readFileSync(process.argv[2], 'utf8'));
8	const showAll = process.argv.includes('--all');
9	
10	// Strip the PyInstaller notice (contains a PID) and normalise nothing else.
11	function norm(s) {
12	  return s.replace(/^\[PYI-\d+:ERROR\].*$/gm, '[PYI:ERROR]');
13	}
14	
15	let pass = 0;
16	const fails = [];
17	for (const args of CASES) {
18	  const a = spawnSync(REF, args, { encoding: 'buffer', env: { ...process.env, COLUMNS: undefined } });
19	  const b = spawnSync('node', ['/output/test10.mjs', ...args], { encoding: 'buffer' });
20	  const ao = a.stdout.toString('binary'), bo = b.stdout.toString('binary');
21	  const ae = norm(a.stderr.toString('binary')), be = norm(b.stderr.toString('binary'));
22	  const ok = ao === bo && ae === be && a.status === b.status;
23	  if (ok) pass++;
24	  else fails.push({ args, py: { out: ao, err: ae, rc: a.status }, js: { out: bo, err: be, rc: b.status } });
25	}
26	
27	console.log(`PASS ${pass}/${CASES.length}`);
28	for (const f of (showAll ? fails : fails.slice(0, 25))) {
29	  console.log('--- ARGS', JSON.stringify(f.args));
30	  if (f.py.out !== f.js.out) { console.log('  PY.out', JSON.stringify(f.py.out)); console.log('  JS.out', JSON.stringify(f.js.out)); }
31	  if (f.py.err !== f.js.err) { console.log('  PY.err', JSON.stringify(f.py.err)); console.log('  JS.err', JSON.stringify(f.js.err)); }
32	  if (f.py.rc !== f.js.rc) console.log('  RC', f.py.rc, 'vs', f.js.rc);
33	}
34	if (fails.length > 25 && !showAll) console.log(`... ${fails.length - 25} more failures`);
35	process.exitCode = fails.length ? 1 : 0;
36

1	#!/usr/bin/env node
2	/**
3	 * Node.js port of `test10.py`.
4	 *
5	 * Reads three typed options, builds the same dict, and prints the canonical
6	 * encoding, the pretty encoding, and the number of chunks the iterative encoder
7	 * produces.  The first two lines are `bytes` reprs because `canonicaljson`
8	 * returns UTF-8 bytes and Python's `print()` reprs anything that is not a `str`.
9	 */
10	
11	import {
12	  encodeCanonicalJson,
13	  encodePrettyPrintedJson,
14	  iterencodeCanonicalJson,
15	} from './lib/canonicaljson.mjs';
16	import { ArgumentParser, SystemExit } from './lib/argparse/parser.mjs';
17	import { PyException, printTraceback } from './lib/pyerrors.mjs';
18	import { pyFloatFromString } from './lib/pyfloat.mjs';
19	import { pyIntFromString } from './lib/pyint.mjs';
20	import { bytesRepr } from './lib/pyrepr.mjs';
21	import { pyDict } from './lib/pytypes.mjs';
22	
23	function main() {
24	  const parser = new ArgumentParser({ prog: 'test10_executable' });
25	  parser.addArgument(['--a'], { type: (text) => text, typeName: 'str', required: true });
26	  parser.addArgument(['--b'], { type: pyIntFromString, typeName: 'int', required: true });
27	  parser.addArgument(['--c'], { type: pyFloatFromString, typeName: 'float', required: true });
28	  const args = parser.parseArgs(process.argv.slice(2));
29	
30	  const data = pyDict([
31	    ['string', args.a],
32	    ['integer', args.b],
33	    ['float', args.c],
34	    ['list', [args.a, args.b, args.c]],
35	  ]);
36	
37	  const canonicalResult = encodeCanonicalJson(data);
38	  const prettyResult = encodePrettyPrintedJson(data);
39	  const canonicalChunks = Array.from(iterencodeCanonicalJson(data));
40	
41	  console.log(bytesRepr(canonicalResult));
42	  console.log(bytesRepr(prettyResult));
43	  console.log(String(canonicalChunks.length));
44	}
45	
46	try {
47	  main();
48	} catch (err) {
49	  if (err instanceof SystemExit) {
50	    process.exitCode = err.code;
51	  } else if (err instanceof PyException) {
52	    printTraceback(err);
53	    process.exitCode = 1;
54	  } else {
55	    throw err;
56	  }
57	}
