1	/**
2	 * A port of `json.JSONEncoder` — specifically of `_make_iterencode()`, the
3	 * pure-Python generator path.
4	 *
5	 * Reproducing the generator faithfully matters: `iterencode()` is observable
6	 * through the *number of chunks* it yields, and the chunk boundaries are an
7	 * artefact of how the original code interleaves separators.  Lists prepend the
8	 * pending separator onto the following item (one chunk per element), whereas
9	 * dicts yield the separator, the key and the key separator as three chunks.
10	 */
11	
12	import { PyValueError, PyTypeError } from '../pyerrors.mjs';
13	import { floatRepr } from '../pyfloat.mjs';
14	import { intRepr } from '../pyint.mjs';
15	import { codePointCompare } from '../pyunicode.mjs';
16	import {
17	  isPyBool,
18	  isPyDict,
19	  isPyFloat,
20	  isPyInt,
21	  isPyList,
22	  isPyNone,
23	  isPyStr,
24	} from '../pytypes.mjs';
25	import { encodeBasestring } from './escape.mjs';
26	
27	/** `sorted(dct.items())` restricted to the key types a dict can actually hold. */
28	function sortItems(entries) {
29	  const keys = entries.map(([key]) => key);
30	  if (keys.every(isPyStr)) {
31	    return entries.slice().sort((a, b) => codePointCompare(a[0], b[0]));
32	  }
33	  if (keys.every((key) => isPyInt(key) || isPyFloat(key) || isPyBool(key))) {
34	    const asNumber = (key) => (isPyBool(key) ? Number(key) : Number(key));
35	    return entries.slice().sort((a, b) => asNumber(a[0]) - asNumber(b[0]));
36	  }
37	  throw new PyTypeError("'<' not supported between instances of dict keys");
38	}
39	
40	export class JSONEncoder {
41	  constructor(options = {}) {
42	    const {
43	      skipkeys = false,
44	      checkCircular = true,
45	      allowNan = true,
46	      sortKeys = false,
47	      indent = null,
48	      separators = null,
49	      defaultFn = null,
50	    } = options;
51	
52	    this.skipkeys = skipkeys;
53	    this.checkCircular = checkCircular;
54	    this.allowNan = allowNan;
55	    this.sortKeys = sortKeys;
56	    this.indent = typeof indent === 'number' ? ' '.repeat(indent) : indent;
57	
58	    if (separators !== null) {
59	      [this.itemSeparator, this.keySeparator] = separators;
60	    } else if (indent !== null) {
61	      // Matches CPython: an indent implies a bare comma so no trailing
62	      // whitespace is emitted before the newline.
63	      this.itemSeparator = ',';
64	      this.keySeparator = ': ';
65	    } else {
66	      this.itemSeparator = ', ';
67	      this.keySeparator = ': ';
68	    }
69	
70	    this.defaultFn = defaultFn;
71	  }
72	
73	  /** `JSONEncoder.default()` — reached only for unsupported types. */
74	  default(value) {
75	    if (this.defaultFn) return this.defaultFn(value);
76	    throw new PyTypeError(`Object of type ${typeof value} is not JSON serializable`);
77	  }
78	
79	  /** The `floatstr()` closure built inside `JSONEncoder.iterencode()`. */
80	  floatstr(value) {
81	    let text;
82	    if (Number.isNaN(value)) text = 'NaN';
83	    else if (value === Infinity) text = 'Infinity';
84	    else if (value === -Infinity) text = '-Infinity';
85	    else return floatRepr(value);
86	
87	    if (!this.allowNan) {
88	      throw new PyValueError(
89	        `Out of range float values are not JSON compliant: ${floatRepr(value)}`,
90	      );
91	    }
92	    return text;
93	  }
94	
95	  /** `JSONEncoder.encode()`. */
96	  encode(value) {
97	    if (isPyStr(value)) return encodeBasestring(value);
98	    return Array.from(this.iterencode(value)).join('');
99	  }
100	
101	  /** `JSONEncoder.iterencode()`, yielding the same chunks in the same order. */
102	  *iterencode(value) {
103	    const markers = this.checkCircular ? new Set() : null;
104	    yield* this.#iterencode(value, 0, markers);
105	  }
106	
107	  *#iterencodeList(lst, indentLevel, markers) {
108	    if (lst.length === 0) {
109	      yield '[]';
110	      return;
111	    }
112	    if (markers !== null) {
113	      if (markers.has(lst)) throw new PyValueError('Circular reference detected');
114	      markers.add(lst);
115	    }
116	
117	    let buf = '[';
118	    let newlineIndent = null;
119	    let separator = this.itemSeparator;
120	    let level = indentLevel;
121	    if (this.indent !== null) {
122	      level += 1;
123	      newlineIndent = `\n${this.indent.repeat(level)}`;
124	      separator = this.itemSeparator + newlineIndent;
125	      buf += newlineIndent;
126	    }
127	
128	    let first = true;
129	    for (const value of lst) {
130	      if (first) first = false;
131	      else buf = separator;
132	
133	      if (isPyStr(value)) yield buf + encodeBasestring(value);
134	      else if (isPyNone(value)) yield `${buf}null`;
135	      else if (value === true) yield `${buf}true`;
136	      else if (value === false) yield `${buf}false`;
137	      else if (isPyInt(value)) yield buf + intRepr(value);
138	      else if (isPyFloat(value)) yield buf + this.floatstr(value);
139	      else {
140	        yield buf;
141	        if (isPyList(value)) yield* this.#iterencodeList(value, level, markers);
142	        else if (isPyDict(value)) yield* this.#iterencodeDict(value, level, markers);
143	        else yield* this.#iterencode(value, level, markers);
144	      }
145	    }
146	
147	    if (newlineIndent !== null) {
148	      level -= 1;
149	      yield `\n${this.indent.repeat(level)}`;
150	    }
151	    yield ']';
152	    if (markers !== null) markers.delete(lst);
153	  }
154	
155	  *#iterencodeDict(dct, indentLevel, markers) {
156	    if (dct.size === 0) {
157	      yield '{}';
158	      return;
159	    }
160	    if (markers !== null) {
161	      if (markers.has(dct)) throw new PyValueError('Circular reference detected');
162	      markers.add(dct);
163	    }
164	
165	    yield '{';
166	    let newlineIndent = null;
167	    let itemSeparator = this.itemSeparator;
168	    let level = indentLevel;
169	    if (this.indent !== null) {
170	      level += 1;
171	      newlineIndent = `\n${this.indent.repeat(level)}`;
172	      itemSeparator = this.itemSeparator + newlineIndent;
173	      yield newlineIndent;
174	    }
175	
176	    let entries = Array.from(dct.entries());
177	    if (this.sortKeys) entries = sortItems(entries);
178	
179	    let first = true;
180	    for (const [rawKey, value] of entries) {
181	      let key = rawKey;
182	      if (isPyStr(key)) {
183	        // already a string
184	      } else if (isPyFloat(key)) key = this.floatstr(key);
185	      else if (key === true) key = 'true';
186	      else if (key === false) key = 'false';
187	      else if (isPyNone(key)) key = 'null';
188	      else if (isPyInt(key)) key = intRepr(key);
189	      else if (this.skipkeys) continue;
190	      else throw new PyTypeError('keys must be str, int, float, bool or None');
191	
192	      if (first) first = false;
193	      else yield itemSeparator;
194	
195	      yield encodeBasestring(key);
196	      yield this.keySeparator;
197	
198	      if (isPyStr(value)) yield encodeBasestring(value);
199	      else if (isPyNone(value)) yield 'null';
200	      else if (value === true) yield 'true';
201	      else if (value === false) yield 'false';
202	      else if (isPyInt(value)) yield intRepr(value);
203	      else if (isPyFloat(value)) yield this.floatstr(value);
204	      else if (isPyList(value)) yield* this.#iterencodeList(value, level, markers);
205	      else if (isPyDict(value)) yield* this.#iterencodeDict(value, level, markers);
206	      else yield* this.#iterencode(value, level, markers);
207	    }
208	
209	    if (newlineIndent !== null) {
210	      level -= 1;
211	      yield `\n${this.indent.repeat(level)}`;
212	    }
213	    yield '}';
214	    if (markers !== null) markers.delete(dct);
215	  }
216	
217	  *#iterencode(value, indentLevel, markers) {
218	    if (isPyStr(value)) yield encodeBasestring(value);
219	    else if (isPyNone(value)) yield 'null';
220	    else if (value === true) yield 'true';
221	    else if (value === false) yield 'false';
222	    else if (isPyInt(value)) yield intRepr(value);
223	    else if (isPyFloat(value)) yield this.floatstr(value);
224	    else if (isPyList(value)) yield* this.#iterencodeList(value, indentLevel, markers);
225	    else if (isPyDict(value)) yield* this.#iterencodeDict(value, indentLevel, markers);
226	    else {
227	      if (markers !== null) {
228	        if (markers.has(value)) throw new PyValueError('Circular reference detected');
229	        markers.add(value);
230	      }
231	      yield* this.#iterencode(this.default(value), indentLevel, markers);
232	      if (markers !== null) markers.delete(value);
233	    }
234	  }
235	}
