1	/**
2	 * A port of the `canonicaljson` package's three public encoders.
3	 *
4	 * All three return UTF-8 `bytes` (a `Uint8Array` here), which is why the
5	 * program's output is a `bytes` repr rather than plain text.  The canonical
6	 * form sorts keys and drops all whitespace; the pretty form sorts keys and
7	 * indents by four spaces.  Neither escapes non-ASCII, and neither tolerates
8	 * NaN or infinities.
9	 */
10	
11	import { JSONEncoder } from './json/encoder.mjs';
12	
13	const utf8 = new TextEncoder();
14	
15	const canonicalEncoder = new JSONEncoder({
16	  allowNan: false,
17	  separators: [',', ':'],
18	  sortKeys: true,
19	});
20	
21	const prettyEncoder = new JSONEncoder({
22	  allowNan: false,
23	  indent: 4,
24	  sortKeys: true,
25	});
26	
27	/** `canonicaljson.encode_canonical_json()` */
28	export function encodeCanonicalJson(value) {
29	  return utf8.encode(canonicalEncoder.encode(value));
30	}
31	
32	/** `canonicaljson.encode_pretty_printed_json()` */
33	export function encodePrettyPrintedJson(value) {
34	  return utf8.encode(prettyEncoder.encode(value));
35	}
36	
37	/**
38	 * `canonicaljson.iterencode_canonical_json()` — yields each chunk of the
39	 * canonical form separately, encoded to UTF-8.
40	 */
41	export function* iterencodeCanonicalJson(value) {
42	  for (const chunk of canonicalEncoder.iterencode(value)) {
43	    yield utf8.encode(chunk);
44	  }
45	}
