1	/**
2	 * The mapping between Python values and their JavaScript stand-ins.
3	 *
4	 * | Python  | here                     |
5	 * |---------|--------------------------|
6	 * | `str`   | `string`                 |
7	 * | `int`   | `bigint`                 |
8	 * | `float` | `number`                 |
9	 * | `bool`  | `boolean`                |
10	 * | `None`  | `null`                   |
11	 * | `list`  | `Array`                  |
12	 * | `dict`  | `Map` (insertion-ordered)|
13	 *
14	 * Keeping `int` and `float` on distinct JavaScript types is what lets the
15	 * encoder reproduce `1` vs `1.0` without carrying wrapper objects around.
16	 */
17	
18	export const isPyStr = (value) => typeof value === 'string';
19	export const isPyInt = (value) => typeof value === 'bigint';
20	export const isPyFloat = (value) => typeof value === 'number';
21	export const isPyBool = (value) => typeof value === 'boolean';
22	export const isPyNone = (value) => value === null;
23	export const isPyList = (value) => Array.isArray(value);
24	export const isPyDict = (value) => value instanceof Map;
25	
26	/** Build a `dict` from `[key, value]` pairs, preserving insertion order. */
27	export function pyDict(entries) {
28	  return new Map(entries);
29	}
30

1	/**
2	 * `json.encoder.encode_basestring()` — the `ensure_ascii=False` string escaper.
3	 *
4	 * Only the two structural characters and the C0 control range are touched;
5	 * every other code point, however exotic, is emitted verbatim and left for the
6	 * UTF-8 step to deal with.  In particular U+007F and the U+2028/U+2029 line
7	 * separators are *not* escaped.
8	 */
9	
10	const ESCAPE_RE = /[\x00-\x1f\\"]/g;
11	
12	const ESCAPE_DCT = Object.create(null);
13	ESCAPE_DCT['\\'] = '\\\\';
14	ESCAPE_DCT['"'] = '\\"';
15	ESCAPE_DCT['\b'] = '\\b';
16	ESCAPE_DCT['\f'] = '\\f';
17	ESCAPE_DCT['\n'] = '\\n';
18	ESCAPE_DCT['\r'] = '\\r';
19	ESCAPE_DCT['\t'] = '\\t';
20	for (let i = 0; i < 0x20; i += 1) {
21	  const ch = String.fromCharCode(i);
22	  if (ESCAPE_DCT[ch] === undefined) {
23	    ESCAPE_DCT[ch] = `\\u${i.toString(16).padStart(4, '0')}`;
24	  }
25	}
26	
27	/** Return `text` as a JSON string literal, quotes included. */
28	export function encodeBasestring(text) {
29	  return `"${text.replace(ESCAPE_RE, (match) => ESCAPE_DCT[match])}"`;
30	}
