  'tab\there', 'nl\nhere', 'cr\rhere', '\x00'.replace('\x00', ''), '\x01\x02\x1f',
  '\x7f', '  ', 'emoji🎉', '𝕏𝕐𝕑', '🇺🇸', 'é́', 'ключ', 'مرحبا',
