  rep('a', 1), rep('a', 2), rep('a', 63), rep('a', 64), rep('a', 65),
  rep('a', 255), rep('a', 256), rep('a', 1000), rep('a', 4096), rep('a', 8192),
  rep('a', 65535), rep('a', 65536), rep('ab', 50000), rep('测', 20000),
  rep('🎉', 10000), rep('"', 500), rep('\\', 500), rep('\n', 500),
  rep('\x01', 500), rep('{},:[]"\\\n\t', 300),
  '"'.repeat(1) + rep(' ', 200),
  rep('x�y'.replace('�', ''), 100),
  'inf', 'nan', 'Infinity', '-Infinity', 'NaN',
  '﻿', '�', '￿', '\u{10ffff}', '\u{effff}',
  rep('\u{10ffff}', 2000),
];

const ints = [
  '0', '-0', '+0', '1', '-1', '+5', '42', '-42', '777', '1000000', '-1000000',
  '2147483647', '2147483648', '-2147483648', '-2147483649',
  '9007199254740991', '9007199254740992', '9007199254740993',
  '-9007199254740993', '18446744073709551615', '18446744073709551616',
  '340282366920938463463374607431768211456',
  '12345678901234567890123', '-12345678901234567890123',
  '99999999999999999999999999999999999999',
  ' 7 ', '1_000', '\n 42\t', '00042', '0_0', '\t\n\v\f\r 8 \r\f\v\n\t',
  '١٢٣', '۹۹۹', '０１２',
  '1' + rep('0', 100), '1' + rep('0', 300), '9'.repeat(100), '9'.repeat(308),
  '-' + '9'.repeat(500), '1'.repeat(1000), '7'.repeat(4299), '7'.repeat(4300),
  '7'.repeat(4301), '-' + '7'.repeat(4300), '-' + '7'.repeat(4301),
  '8'.repeat(5000), '3'.repeat(10000),
  '0'.repeat(5000) + '1',
  '-' + '0'.repeat(5000) + '1',
];

const floats = [
  '0', '0.0', '-0.0', '1', '1.0', '-1.0', '0.5', '2.71828', '-123.456',
  '3.141592653589793', '0.30000000000000004',
  '1e10', '1e15', '1e16', '1e17', '1e21', '1e22', '1e100', '1e300', '1e307',
  '1e308', '1.7976931348623157e308', '2.2250738585072014e-308',
  '5e-324', '4.9406564584124654e-324', '1e-323', '1e-320', '1e-310',
  '1e-4', '1e-5', '1e-6', '1e-7', '1e-10',
  '1234567890123456.0', '12345678901234567.0', '123456789012345.6',
  '100000000000000000000.0', '123456789012345678901234567890.5',
  '9007199254740993.0', '999999999999999999999.0',
  '.5', '5.', '1.e5', '+.5', '1_0.5', '1.5e1_0', ' 2.5 ', '-1e-5',
  '1' + rep('0', 400) + '.0',
  '0.' + rep('0', 400) + '1',
  '1.' + rep('2', 500),
  '1e' + '9'.repeat(20),
  '1e-' + '9'.repeat(20),
  'nan', 'NaN', '-nan', 'inf', '-inf', 'Infinity', '-Infinity', 'infinity',
  '1e400', '-1e400', '1e-400', '-1e-400',
];

const cases = [];
const push = (v) => cases.push(v);

// 1. Full cross product of a compact "spine" of each axis (all three vary).
const spineS = ['', 'x', 'unicode测试', rep('a', 4096), rep('🎉', 3000), '"\\\n\x01'];
const spineI = ['0', '-1', '9007199254740993', '7'.repeat(4300), '7'.repeat(4301), '١٢٣'];
