  for (let i = 0; i < len; i += 1) {
    const r = rnd();
    if (r < 0.3) s += String.fromCharCode(32 + Math.floor(rnd() * 95));
    else if (r < 0.5) s += String.fromCharCode(1 + Math.floor(rnd() * 0x1f));
    else if (r < 0.78) s += String.fromCodePoint(0x80 + Math.floor(rnd() * 0xd000));
    else s += String.fromCodePoint(0x10000 + Math.floor(rnd() * 0xf0000));
  }
  return s;
};
const randInt = () => {
  const r = rnd();
  if (r < 0.35) return String(Math.floor((rnd() - 0.5) * 1e12));
  if (r < 0.75) {
    const d = 1 + Math.floor(rnd() * (rnd() < 0.15 ? 4400 : 40));
    let out = '';
    for (let i = 0; i < d; i += 1) out += Math.floor(rnd() * 10);
    return (rnd() < 0.3 ? '-' : '') + out;
  }
  return pick(ints);
};
const randFloat = () => {
  const r = rnd();
  if (r < 0.25) return String((rnd() - 0.5) * 10 ** Math.floor(rnd() * 60 - 30));
  if (r < 0.45) return `${(rnd() * 10).toFixed(Math.floor(rnd() * 18))}e${Math.floor(rnd() * 700 - 350)}`;
  if (r < 0.6) return String(rnd() * Number.MAX_SAFE_INTEGER);
  if (r < 0.7) return `${rnd() < 0.5 ? '-' : ''}0.${'0'.repeat(Math.floor(rnd() * 320))}${1 + Math.floor(rnd() * 9)}`;
  return pick(floats);
};
for (let i = 0; i < 700; i += 1) {
  push(['--a', rnd() < 0.75 ? randStr() : pick(strings), '--b', randInt(), '--c', randFloat()]);
}

// 4. Order-shuffled / '=' forms so the same values arrive by other argv shapes.
for (let i = 0; i < 60; i += 1) {
  const s = pick(strings), a = pick(ints), f = pick(floats);
  const forms = [
    ['--c', f, '--a', s, '--b', a],
    [`--a=${s}`, `--b=${a}`, `--c=${f}`],
    ['--b', a, '--c', f, '--a', s],
  ];
  push(pick(forms));
}

const bad = (s) => s.includes('\0')
  || /[\uD800-\uDFFF]/.test(s.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g, ''));
const clean = cases.filter((v) => v.every((s) => !bad(s)));
writeFileSync('/tmp/diff/chunk-count-cases.json', JSON.stringify(clean));
console.log(`wrote ${clean.length} cases (dropped ${cases.length - clean.length})`);
